-- CF-247 Wave 2: priority country registers pre-staged as induction drafts (Platform Admin 17 Nov 2026 23:02, chat S1-RM-Design).
-- Nine drafts in pipeline.layer1_source_inductions for the United Kingdom, Ireland, the United States and Canada: target record type, registration
-- scheme where one is registered, source address, connector, cadence, the 90-day staging keep period, and category mappings where the published
-- field names are known. A draft is not a source: nothing is added to pipeline.sources, nothing is scheduled, nothing reads the web, and
-- pipeline.source_retention_policies is not written (the keep period is set by public.admin_source_retention_set when the Platform Admin
-- activates a draft, which saves the source paused). Licence terms are left pending for a person to confirm.
-- Not seeded: IRCC Designated Learning Institutions. It is already a live Layer 1 source with its own reader (layer1-ca-live); a second copy
-- would double it. Only the PGWP field-of-study list is drafted for Canada.
-- Replaces: nothing
-- Retires: nothing
-- Applies twice: a draft is added only when no induction (in any state) has its country, source address and target record type.

do $pre$ begin
  if to_regclass('pipeline.layer1_source_inductions') is null then raise exception 'prerequisite missing: pipeline.layer1_source_inductions (migration 20261117193000)'; end if;
  if to_regprocedure('security.layer1_record_types_v1()') is null then raise exception 'prerequisite missing: security.layer1_record_types_v1() (migration 20261117203000)'; end if;
  if (select count(*) from ref.countries where iso_alpha2 in ('GB', 'IE', 'US', 'CA')) <> 4 then raise exception 'prerequisite missing: GB, IE, US and CA in ref.countries'; end if;
  if (select count(*) from ref.registration_schemes s where (s.scheme, s.kind, s.country_code) in (('uk_ofs', 'provider_registration', 'GB'), ('ie_qqi', 'provider_registration', 'IE'),
       ('ie_qqi', 'course_registration', 'IE'), ('us_ipeds', 'provider_registration', 'US'), ('pgwp', 'work_eligibility', 'CA'))) <> 5 then
    raise exception 'prerequisite missing: the registration schemes uk_ofs, ie_qqi (provider and course), us_ipeds and pgwp in ref.registration_schemes';
  end if;
  if (select count(*) from ref.enrichment_categories where category_key in ('course_basics', 'campus_location', 'provider_profile', 'recognition_registration')) <> 4 then
    raise exception 'prerequisite missing: the published enrichment categories (migration 20261117213000)';
  end if;
end $pre$;

