insert into pipeline.layer1_source_inductions(country_code, payload, mappings)
select s.country_code,
       -- the keep period the Platform Admin asked for (17 Nov 2026 23:02); a value of this draft, changed in the wizard's step 4, applied to the
       -- retention table only on activation. Editions are kept as with every wizard draft.
       s.payload || jsonb_build_object('staging_keep_days', 90, 'edition_archiving', true),
       s.mappings
from seed s
where not exists (select 1 from pipeline.layer1_source_inductions i where i.country_code = s.country_code and i.payload->>'source_url' = s.payload->>'source_url'
                    and i.payload->>'target_record_type' = s.payload->>'target_record_type');

do $post$ declare v_bad text; begin
  if (select count(*) from pipeline.layer1_source_inductions i where i.payload->>'notes' like 'Wave 2 draft, pre-staged 17 Nov 2026.%') < 9 then raise exception 'post-check: fewer than nine Wave 2 drafts'; end if;
  select string_agg(i.payload->>'source_label', ', ') into v_bad from pipeline.layer1_source_inductions i
   where i.payload->>'notes' like 'Wave 2 draft, pre-staged 17 Nov 2026.%'
     and (not exists (select 1 from jsonb_array_elements(security.layer1_record_types_v1()) t where t->>'key' = i.payload->>'target_record_type')
          or (i.payload->>'scheme' <> '' and not exists (select 1 from ref.registration_schemes r where r.scheme = i.payload->>'scheme' and r.kind = i.payload->>'scheme_kind' and r.country_code = i.country_code))
          or exists (select 1 from jsonb_array_elements(i.mappings) m where m->>'category_key' <> '' and not exists (select 1 from ref.enrichment_categories c where c.category_key = m->>'category_key'))
          or exists (select 1 from jsonb_array_elements(i.mappings) m where m->>'target_field' <> '' and not exists (select 1 from ref.enrichment_category_fields f where f.field = m->>'target_field' and f.category_key = m->>'category_key')));
  if v_bad is not null then raise exception 'post-check: a draft names an unknown record type, scheme, category or field: %', v_bad; end if;
end $post$;
